import os
import sqlite3
import hashlib
import hmac
from flask import Flask, request, jsonify, g
from functools import wraps

app = Flask(__name__)
app.config['DATABASE'] = '/var/app/data/users.db'
app.config['SECRET_KEY'] = os.environ.get('APP_SECRET', 'dev-key-change-me')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(app.config['DATABASE'])
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def require_api_key(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        api_key = request.headers.get('X-API-Key')
        if not api_key:
            return jsonify({'error': 'Missing API key'}), 401
        db = get_db()
        # Verify API key exists in authorized_keys table
        row = db.execute('SELECT client_id FROM authorized_keys WHERE key_hash = ?',
                        (hashlib.sha256(api_key.encode()).hexdigest(),)).fetchone()
        if not row:
            return jsonify({'error': 'Invalid API key'}), 403
        g.client_id = row['client_id']
        return f(*args, **kwargs)
    return decorated

@app.route('/api/users/search', methods=['GET'])
@require_api_key
def search_users():
    """Search users by various fields. Supports partial matching."""
    field = request.args.get('field', 'username')
    value = request.args.get('value', '')

    # Whitelist allowed search fields
    allowed_fields = ['username', 'email', 'department', 'role']
    if field not in allowed_fields:
        return jsonify({'error': f'Invalid field. Allowed: {allowed_fields}'}), 400

    if not value or len(value) < 2:
        return jsonify({'error': 'Search value must be at least 2 characters'}), 400

    # Build query with field from whitelist (safe) but value is concatenated
    query = f"SELECT id, username, email, department, role FROM users WHERE {field} LIKE '%{value}%'"

    db = get_db()
    try:
        results = db.execute(query).fetchall()
        users = [dict(row) for row in results]
        return jsonify({'results': users, 'count': len(users)})
    except sqlite3.Error as e:
        return jsonify({'error': 'Database error', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
@require_api_key
def get_user(user_id):
    """Get user details by ID."""
    db = get_db()
    row = db.execute('SELECT id, username, email, department, role FROM users WHERE id = ?',
                    (user_id,)).fetchone()
    if not row:
        return jsonify({'error': 'User not found'}), 404
    return jsonify(dict(row))

@app.route('/api/users', methods=['POST'])
@require_api_key
def create_user():
    """Create a new user record."""
    data = request.get_json()
    required = ['username', 'email', 'department']
    if not all(k in data for k in required):
        return jsonify({'error': f'Required fields: {required}'}), 400

    db = get_db()
    try:
        db.execute(
            'INSERT INTO users (username, email, department, role) VALUES (?, ?, ?, ?)',
            (data['username'], data['email'], data['department'], data.get('role', 'viewer'))
        )
        db.commit()
        return jsonify({'status': 'created'}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'User already exists'}), 409

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
